/**
 * Jinx Lleech + Slayer: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lleech
 * Wiki: https://wiki.bloodontheclocktower.com/Slayer
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { dayUseDeath } from '#lib/core/rules/day/day-claims.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { killsMarkedBy } from '#lib/core/rules/jinxes/jinx-effects.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Lleech + Slayer jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lleech', 'slayer');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lleech')?.name).toBe('Lleech');
		expect(data.byId.get('slayer')?.name).toBe('Slayer');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lleech', 'slayer'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lleech'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['slayer'])).not.toContain(jinx);
	});

	describe('the Slayer slaying the Lleech host kills the host', () => {
		const ids = ['slayer', 'lleech', 'chef', 'empath', 'monk'];
		// The Lleech's host is the Chef.
		const base = scenario(ids, { script: scriptOf(ids) }).reminder('chef', 'lleech', 'Poisoned');

		it("is data in the Slayer's rules", () => {
			// Wiki: "If the Slayer slays the Lleech host, the host dies."
			expect(ownJinxRules(base.game, 'slayer', 'lleech', base.characters)).toEqual({
				killsMarked: { token: 'Poisoned' }
			});
		});

		it('kills the host the Slayer shoots', () => {
			// Wiki: "If the Slayer slays the Lleech host, the host dies."
			expect(killsMarkedBy(base.game, 'slayer', base.seat('chef'), base.characters)).toBe('lleech');
			expect(dayUseDeath(base.game, 'slayer', base.seat('chef'), base.characters)).toBe('dies');
		});

		it('kills no other good player the Slayer shoots', () => {
			// Wiki: "the Lleech host"
			expect(dayUseDeath(base.game, 'slayer', base.seat('empath'), base.characters)).toBe('no');
		});
	});
});
